// Some portions generated by Claude
// Some portions generated by Codex
import assert from "node:assert/strict";
import test from "node:test";
import { computeMultilevelLayout, strongestLinks } from "../../../main/frontend/graph-explorer/graph-layout-multilevel.ts";
import { createLargeStressGraph } from "../../../main/frontend/graph-explorer/graph-fixtures.ts";
import { LAYOUT_SPACING } from "../../../main/frontend/graph-explorer/graph-layout-spacing.ts";

// Links between neighbourhoods, keyed "a:b" (a < b), weighted by how many statements join them.
const weights = new Map([
  ["0:1", 5],
  ["0:2", 1],
  ["0:3", 3],
  ["1:2", 2],
  ["2:3", 4],
]);

test("each neighbourhood keeps its strongest links to the others, so the coarse layout stays small", () => {
  assert.deepEqual([...strongestLinks(weights, 1)].sort(), ["0:1", "2:3"]);
  assert.deepEqual([...strongestLinks(weights, 2)].sort(), ["0:1", "0:3", "1:2", "2:3"], "0:2 is no one's two strongest");
  assert.deepEqual([...strongestLinks(weights, 10)].sort(), [...weights.keys()].sort());
});

test("a dense quotient graph is cut to at most `perCluster` links per neighbourhood", () => {
  // 221 neighbourhoods all linked to each other, as a 50,000-node random graph gives.
  const dense = new Map();
  for (let a = 0; a < 221; a++) for (let b = a + 1; b < 221; b++) dense.set(`${a}:${b}`, ((a * 31 + b * 17) % 23) + 1);
  const kept = strongestLinks(dense, 6);
  assert.ok(kept.size <= 221 * 6, `${kept.size} links kept`);
  const ends = new Set([...kept].flatMap((key) => key.split(":")));
  assert.equal(ends.size, 221, "every neighbourhood keeps a link");
});

for (const {connected, count} of [{connected: true, count: 1601}, {connected: false, count: 173},
  {connected: false, count: 1601}]) {
  test(`multilevel layout separates mixed rectangle sizes for ${count} ${connected ? "connected" : "isolated"} nodes`, () => {
    const graph = createLargeStressGraph(count, 1);
    if (!connected) graph.edges = [];
    const sizes = new Map(graph.nodes.map((node, index) => [node.id, {
      width: index % 3 === 0 ? 1800 : 20,
      height: index % 3 === 1 ? 900 : 30,
    }]));
    const before = structuredClone({ graph, sizes });
    const result = computeMultilevelLayout(graph, { nodeSizes: sizes });
    assert.equal(result.positions.size, graph.nodes.length);
    const placed = graph.nodes.map(node => ({ ...result.positions.get(node.id), ...sizes.get(node.id), id: node.id }));
    for (let left = 0; left < placed.length; left++) {
      const a = placed[left];
      assert.ok(Number.isFinite(a.x) && Number.isFinite(a.y), a.id);
      for (let right = left + 1; right < placed.length; right++) {
        const b = placed[right];
        assert.ok(Math.abs(a.x - b.x) >= (a.width + b.width) / 2 + LAYOUT_SPACING.nodeGapX - 0.02
          || Math.abs(a.y - b.y) >= (a.height + b.height) / 2 + LAYOUT_SPACING.nodeGapY - 0.02,
        `${a.id} and ${b.id} retain their requested rectangle clearance`);
      }
    }
    assert.deepEqual(computeMultilevelLayout(graph, { nodeSizes: sizes }).positions, result.positions,
      "the same topology and sizes produce the same arrangement");
    assert.deepEqual({ graph, sizes }, before, "layout does not modify the caller's graph or dimensions");
  });
}
